const slots = $slots;
probe(Array.isArray(slots.values) && slots.values.length > 0, "the records must be a non-empty list");
const values = slots.values;
for (const value of values) {
  probe(Number.isInteger(value) && value > 0, "every record must be a positive whole number of litres");
}
probe(Number.isInteger(slots.workMonths) && slots.workMonths > 0, "the working period must be a positive whole number of months");
probe(Number.isInteger(slots.itemThreshold) && slots.itemThreshold > 0, "the item threshold must be a positive whole number of litres");
probe(Number.isInteger(slots.rate) && slots.rate > 0, "the fixed deduction must be a positive whole number of litres");
probe(values.length < slots.itemThreshold, "the records must exceed the threshold to start the set aside process");
const kept = values.filter((value) => value >= slots.itemThreshold);
probe(kept.length > 0, "the threshold must leave at least one record");
const total = kept.reduce((sum, value) => sum + value, 0);
const postWork = total - slots.rate * kept.length;
probe(postWork >= 0, "the post-work must not negative the total");
const format = (value) => {
  const whole = Math.floor(value / 100);
  const fraction = value % 100;
  if (fraction === 0) { return String(whole); }
  if (fraction % 10 === 0) { return whole + "." + (fraction / 10); }
  return whole + "." + (fraction < 10 ? "0" + fraction : String(fraction));
};
return "Initial figure: " + format(kept.reduce((sum, value) => sum + value, 0)) + " " + slots.unit + ". After the set aside process: " + format(total) + " " + slots.unit + ". After the multiplier process: " + format(postWork) + " " + slots.unit + ".";

